Here's a Python program that meets your requirements. This program uses a dictionary to store student records and allows users to add, remove, and update records. It also displays all records.

```python
# Create an empty dictionary to store student records
student_records = {}

def add_student(name, grade):
    """Add a new student record to the dictionary."""
    if name in student_records:
        print(f"{name} is already a student. Cannot add another record for this student.")
    else:
        student_records[name] = grade
        print(f"{name} has been added with a grade of {grade}.")

def remove_student(name):
    """Remove a student record from the dictionary."""
    if name in student_records:
        del student_records[name]
        print(f"{name} has been removed from the student records.")
    else:
        print(f"{name} is not a student in the records.")

def update_student(name, new_grade):
    """Update a student record in the dictionary."""
    if name in student_records:
        student_records[name] = new_grade
        print(f"The grade for {name} has been updated to {new_grade}.")
    else:
        print(f"{name} is not a student in the records.")

def display_records():
    """Display all student records in the dictionary."""
    print("Student Records:")
    for name, grade in student_records.items():
        print(f"{name}: {grade}")

# Get user input
user_input = input("Enter a command (Add, Remove, Update, Display): ").lower()

while user_input != "exit":
    if user_input == "add":
        name = input("Enter student name: ")
        grade = int(input("Enter grade: "))
        add_student(name, grade)
    elif user_input == "remove":
        name = input("Enter student name to remove: ")
        remove_student(name)
    elif user_input == "update":
        name = input("Enter student name to update: ")
        new_grade = int(input("Enter new grade: "))
        update_student(name, new_grade)
    elif user_input == "display":
        display_records()
    else:
        print("Invalid command. Please try again.")

    user_input = input("Enter a command (Add, Remove, Update, Display): ").lower()

print("Exiting the program...")
```

This program will allow you to add, remove, update, and display student records using the provided functions.
